INSERT INTO `mod_forever_journal_lore` (`ID`, `Zone`, `Kind`, `SortOrder`, `Faction`, `Races`, `Classes`, `Era`, `Title`, `Body`, `Sources`) VALUES
(3457000, 3457, 0, 1, 0, 0, 0, 0, 'Karazhan', 'The tower of Medivh, the Last Guardian of Tirisfal. His mother, the Guardian Aegwynn, built it in secret on a nexus of ley lines some six hundred years before the First War, as a refuge from the Council of Tirisfal and a conduit for the ley lines'' power. The energies running through it warped reality around it.\n\nMedivh amassed a library of writings and artifacts that dwarfs even the Kirin Tor''s. After Khadgar, Anduin Lothar and Garona slew him, the tower sealed itself off from the world. Now it has woken. An evil presence has taken it as its own, its halls crawl with spirits and demons, and Medivh''s magic is so great that it still echoes through them.', 'warcraft.wiki.gg: Karazhan (introduction, History)'),
(3457001, 3457, 1, 1, 0, 0, 0, 0, 'The Servants'' Quarters and the Stables', 'The tower''s lower levels: the stables where the huntsman tends Midnight, the strongest horse in them, and the servants'' quarters, where great beasts lurk in the dark.', 'warcraft.wiki.gg: Attumen the Huntsman; warcraft.wiki.gg: Karazhan'),
(3457002, 3457, 1, 2, 0, 0, 0, 0, 'The Banquet Hall', 'Where the steward still tends to the guests of a party that never ended. Medivh''s celebrations here were notoriously depraved.', 'warcraft.wiki.gg: Moroes; warcraft.wiki.gg: Maiden of Virtue'),
(3457003, 3457, 1, 3, 0, 0, 0, 0, 'The Guest Chambers', 'Rooms where the tower''s guests stayed, watched over by a titanic watcher who came to purify them of their corruption and never left.', 'warcraft.wiki.gg: Maiden of Virtue'),
(3457004, 3457, 1, 4, 0, 0, 0, 0, 'The Opera Hall', 'Karazhan''s theatre, where the ghostly players still put on their shows for whatever audience wanders in, and Barnes the stage manager still runs the stage. The play changes from night to night: a tragedy of star-crossed lovers, a grandmother and a wolf, a girl from far away and her strange companions. The audience is cast in the leading roles.', 'warcraft.wiki.gg: Romulo; warcraft.wiki.gg: The Big Bad Wolf; warcraft.wiki.gg: The Crone'),
(3457005, 3457, 1, 5, 0, 0, 0, 0, 'The Menagerie', 'Medivh''s collection of things beautiful, magical and unique, many since lost or broken, still guarded by its arcane golem with undiminished ferocity.', 'warcraft.wiki.gg: The Curator'),
(3457006, 3457, 1, 6, 0, 0, 0, 0, 'The Guardian''s Library', 'The greatest library of the Last Guardian. A satyr hides behind its shelves in a secret passage, calling demons into it, and in a sealed round chamber at its heart lingers the shade of Medivh''s father.', 'warcraft.wiki.gg: Shade of Aran; warcraft.wiki.gg: Terestian Illhoof'),
(3457007, 3457, 1, 7, 0, 0, 0, 0, 'The Celestial Watch', 'Medivh''s personal observatory, now the lair of a nether dragon.', 'warcraft.wiki.gg: Netherspite'),
(3457008, 3457, 1, 8, 0, 0, 0, 0, 'The Gamesman''s Hall', 'A great chessboard whose pieces are living things. The echo of Medivh waits to play against anyone who sits down across from him, and he does not always play fair.', 'warcraft.wiki.gg: Chess Event'),
(3457009, 3457, 1, 9, 0, 0, 0, 0, 'The Netherspace', 'The very top of the tower, open to the Nether, where the presence that has taken Karazhan holds court.', 'warcraft.wiki.gg: Prince Malchezaar'),
(3457010, 3457, 1, 10, 0, 0, 0, 0, 'The Master''s Terrace', 'A terrace high on the tower, scorched long ago by dragonfire, where Medivh once fought a dragon.', 'warcraft.wiki.gg: Nightbane (tactics)'),
(3457030, 3457, 2, 1, 0, 0, 0, 0, 'Attumen the Huntsman', 'A spectral huntsman, the proud owner of Midnight. Threaten the horse and he comes riding to its defence.', 'warcraft.wiki.gg: Attumen the Huntsman'),
(3457031, 3457, 2, 2, 0, 0, 0, 0, 'Moroes', 'Medivh''s steward: talented, loyal, sombre and somewhat paranoid from the strange visions that come to those who live in Karazhan. He knows he is undead, and that something raises him again each time he is destroyed. Given the choice he would rather stay dead, but he makes do, and keeps the tower clean.', 'warcraft.wiki.gg: Moroes'),
(3457032, 3457, 2, 3, 0, 0, 0, 0, 'The Maiden of Virtue', 'A titanic watcher drawn to Karazhan by the depravity of Medivh''s revels. She tried to purify the tower and failed. She stands motionless until roused by someone she takes for Medivh, or someone as debauched; her judgement has dulled over the years, and it takes little to set her off.', 'warcraft.wiki.gg: Maiden of Virtue (Biography)'),
(3457033, 3457, 2, 4, 0, 0, 0, 0, 'The Opera Company', 'Romulo and Julianne, the Big Bad Wolf, Dorothee and her companions and the Crone: the ghostly players of the Opera Hall, still performing for their audience long after their own deaths.', 'warcraft.wiki.gg: Romulo; warcraft.wiki.gg: The Big Bad Wolf; warcraft.wiki.gg: The Crone'),
(3457034, 3457, 2, 5, 0, 0, 0, 0, 'The Curator', 'A massive, surprisingly fast arcane golem, made to protect Karazhan''s treasures.', 'warcraft.wiki.gg: The Curator'),
(3457035, 3457, 2, 6, 0, 0, 0, 0, 'Terestian Illhoof', 'A satyr hiding in a secret passage behind the library''s bookshelves, from which he keeps the demons coming.', 'warcraft.wiki.gg: Terestian Illhoof'),
(3457036, 3457, 2, 7, 0, 0, 0, 0, 'The Shade of Aran', 'The spirit of Nielas Aran, Medivh''s father, a mage of the Council of Tirisfal, bound to his son''s library.', 'warcraft.wiki.gg: Shade of Aran'),
(3457037, 3457, 2, 8, 0, 0, 0, 0, 'Netherspite', 'An immense nether dragon, the only dragon inside the tower, lurking in the Celestial Watch.', 'warcraft.wiki.gg: Netherspite'),
(3457038, 3457, 2, 9, 0, 0, 0, 0, 'Prince Malchezaar', 'An eredar lord of the Burning Legion, who took control of Karazhan. When he came, or what he wanted here, no one knows. He came while agents of the Violet Eye were still alive inside the tower, shortly before it sealed. He collects rare weapons.', 'warcraft.wiki.gg: Prince Malchezaar'),
(3457039, 3457, 2, 10, 0, 0, 0, 0, 'Nightbane', 'A fiery skeletal dragon. Once he was Arcanagos of the blue dragonflight, who came to Karazhan and fell to Medivh. Medivh made him into this.', 'warcraft.wiki.gg: Nightbane (tactics)'),
(3457050, 3457, 3, 1, 0, 0, 0, 0, 'The Last Guardian', 'Medivh was the son of the Guardian Aegwynn and the mage Nielas Aran. When he came of age, the Guardian''s power awoke in him, and with it the spirit of Sargeras, which Aegwynn had unknowingly carried since she defeated the Dark Titan''s avatar. From this tower, possessed, Medivh reached across to Draenor, to Gul''dan, and helped open the Dark Portal.\n\nHis apprentice Khadgar, Anduin Lothar and the half-orc Garona came here and killed him. The tower has kept its secrets ever since.', 'warcraft.wiki.gg: Karazhan (The Last Guardian); warcraft.wiki.gg: Karazhan (introduction)');
